import React from 'react';

const QuestionCard = ({ index, formData, availableOptions = [], maskAnswers, onUpdate }) => {
  const isMismatch = formData.confirmedAnswerText && (formData.answerText !== formData.confirmedAnswerText);
  const inputType = maskAnswers ? "password" : "text";

  return (
    <div className="question-row">
      <label className="row-label">Question {index + 1}</label>
      
      <select
        className="select-field"
        value={formData.selectedQuestion}
        onChange={e => onUpdate(index, 'selectedQuestion', e.target.value)}
      >
        <option value="">-- Select a Question --</option>
        {availableOptions.map((item) => (
          <option key={item.q_id} value={item.question}>
            {item.question}
          </option>
        ))}
      </select>

      <div className="input-split">
        <input
          className="input-base"
          type={inputType}
          placeholder="Answer"
          value={formData.answerText}
          onChange={e => onUpdate(index, 'answerText', e.target.value)}
        />
        
        <input
          className={`input-base ${isMismatch ? 'error-border' : ''}`}
          type={inputType}
          placeholder="Confirm"
          value={formData.confirmedAnswerText}
          onChange={e => onUpdate(index, 'confirmedAnswerText', e.target.value)}
        />
      </div>
      
      {isMismatch && <span className="error-hint">Answers do not match</span>}
    </div>
  );
};

export default QuestionCard;
